CREATE TABLE center_members(employee_id TEXT NOT NULL REFERENCES employees(id),center TEXT NOT NULL CHECK(center IN ('marketing','design')),PRIMARY KEY(employee_id,center));
CREATE TABLE marketing_spends(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,record_date TEXT NOT NULL,channel TEXT NOT NULL,expense_type TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL,activity TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',owner_id TEXT NOT NULL REFERENCES employees(id),project_id TEXT REFERENCES projects(id),reference TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','void')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE design_tasks(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,task_type TEXT NOT NULL,brief TEXT NOT NULL,requested_date TEXT NOT NULL,due_date TEXT,original_due_date TEXT,owner_id TEXT REFERENCES employees(id),team TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'queued',version_label TEXT NOT NULL DEFAULT '',revision_count INTEGER NOT NULL DEFAULT 0,result_reference TEXT NOT NULL DEFAULT '',confirmation TEXT NOT NULL DEFAULT '',change_reason TEXT NOT NULL DEFAULT '',handoff_note TEXT NOT NULL DEFAULT '',completed_at TEXT,accepted_at TEXT,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX design_tasks_project ON design_tasks(project_id,status);
CREATE TABLE center_events(id TEXT PRIMARY KEY,entity TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',actor_id TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL);
CREATE TRIGGER center_events_no_update BEFORE UPDATE ON center_events BEGIN SELECT RAISE(ABORT,'业务过程记录不可覆盖'); END;
CREATE TRIGGER center_events_no_delete BEFORE DELETE ON center_events BEGIN SELECT RAISE(ABORT,'业务过程记录不可删除'); END;
CREATE TABLE crm_followups(id TEXT PRIMARY KEY,entity TEXT NOT NULL CHECK(entity IN ('leads','opportunities')),entity_id TEXT NOT NULL,contact_date TEXT NOT NULL,result TEXT NOT NULL,next_action TEXT NOT NULL,next_date TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL);
CREATE TABLE center_targets(id TEXT PRIMARY KEY,center TEXT NOT NULL,month TEXT NOT NULL,metric TEXT NOT NULL,currency TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>=0),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES employees(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(center,month,metric,currency));
ALTER TABLE crm_leads ADD COLUMN region TEXT NOT NULL DEFAULT '';
ALTER TABLE crm_leads ADD COLUMN activity TEXT NOT NULL DEFAULT '';
ALTER TABLE crm_leads ADD COLUMN validity_reason TEXT NOT NULL DEFAULT '';
